    CreateEventSourceMappingRequest.add_member(:batch_size, Smithy::Schema::Shapes::ShapeRef.new(shape: BatchSize, member_name: 'BatchSize', traits: {"smithy.api#documentation" => "<p>The maximum number of records in each batch that Lambda pulls from your stream or queue and sends to your function. Lambda passes all of the records in the batch to the function in a single call, up to the payload limit for synchronous invocation\n  (6 MB).</p>\n         <ul>\n            <li>\n               <p>\n                  <b>Amazon Kinesis</b> – Default 100. Max 10,000.</p>\n            </li>\n            <li>\n               <p>\n                  <b>Amazon DynamoDB Streams</b> – Default 100. Max 10,000.</p>\n            </li>\n            <li>\n               <p>\n                  <b>Amazon Simple Queue Service</b> – Default 10. For standard queues the max is 10,000. For FIFO queues the max is 10.</p>\n            </li>\n            <li>\n               <p>\n                  <b>Amazon Managed Streaming for Apache Kafka</b> – Default 100. Max 10,000.</p>\n            </li>\n            <li>\n               <p>\n                  <b>Self-managed Apache Kafka</b> – Default 100. Max 10,000.</p>\n            </li>\n            <li>\n               <p>\n                  <b>Amazon MQ (ActiveMQ and RabbitMQ)</b> – Default 100. Max 10,000.</p>\n            </li>\n            <li>\n               <p>\n                  <b>DocumentDB</b> – Default 100. Max 10,000.</p>\n            </li>\n         </ul>"}))
