    GetEventSourceMappingOutput.add_member(:batch_size, Smithy::Schema::Shapes::ShapeRef.new(shape: BatchSize, member_name: 'BatchSize', traits: {"smithy.api#documentation" => "<p>The maximum number of records in each batch that Lambda pulls from your stream or queue and sends to your function. Lambda passes all of the records in the batch to the function in a single call, up to the payload limit for synchronous invocation (6 MB).</p>\n         <p>Default value: Varies by service. For Amazon SQS, the default is 10. For all other services, the default is 100.</p>\n         <p>Related setting: When you set <code>BatchSize</code> to a value greater than 10, you must set <code>MaximumBatchingWindowInSeconds</code> to at least 1.</p>"}))
    GetEventSourceMappingOutput.add_member(:maximum_batching_window_in_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: MaximumBatchingWindowInSeconds, member_name: 'MaximumBatchingWindowInSeconds', traits: {"smithy.api#documentation" => "<p>The maximum amount of time, in seconds, that Lambda spends gathering records before invoking the function.\n  You can configure <code>MaximumBatchingWindowInSeconds</code> to any value from 0 seconds to 300 seconds in increments of seconds.</p>\n         <p>For streams and Amazon SQS event sources, the default batching window is 0 seconds. For Amazon MSK, Self-managed Apache Kafka, Amazon MQ, and DocumentDB event sources, the default\n  batching window is 500 ms. Note that because you can only change <code>MaximumBatchingWindowInSeconds</code> in increments of seconds, you cannot revert back to the 500 ms default batching window after you have changed it.\n  To restore the default batching window, you must create a new event source mapping.</p>\n         <p>Related setting: For streams and Amazon SQS event sources, when you set <code>BatchSize</code> to a value greater than 10, you must set <code>MaximumBatchingWindowInSeconds</code> to at least 1.</p>"}))
    GetEventSourceMappingOutput.add_member(:parallelization_factor, Smithy::Schema::Shapes::ShapeRef.new(shape: ParallelizationFactor, member_name: 'ParallelizationFactor', traits: {"smithy.api#documentation" => "<p>(Kinesis and DynamoDB Streams only) The number of batches to process concurrently from each shard. The default value is 1.</p>"}))
