    PutFunctionEventInvokeConfigOutput.add_member(:destination_config, Smithy::Schema::Shapes::ShapeRef.new(shape: DestinationConfig, member_name: 'DestinationConfig', traits: {"smithy.api#documentation" => "<p>A destination for events after they have been sent to a function for processing.</p>\n         <p class=\"title\">\n            <b>Destinations</b>\n         </p>\n         <ul>\n            <li>\n               <p>\n                  <b>Function</b> - The Amazon Resource Name (ARN) of a Lambda function.</p>\n            </li>\n            <li>\n               <p>\n                  <b>Queue</b> - The ARN of a standard SQS queue.</p>\n            </li>\n            <li>\n               <p>\n                  <b>Bucket</b> - The ARN of an Amazon S3 bucket.</p>\n            </li>\n            <li>\n               <p>\n                  <b>Topic</b> - The ARN of a standard SNS topic.</p>\n            </li>\n            <li>\n               <p>\n                  <b>Event Bus</b> - The ARN of an Amazon EventBridge event bus.</p>\n            </li>\n         </ul>\n         <note>\n            <p>S3 buckets are supported only for on-failure destinations. To retain records of successful invocations, use another destination type.</p>\n         </note>"}))
